import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64

.visible .entry min_reduce_dim_kernel(
    .param .u64 p_in,
    .param .u64 p_out,
    .param .u32 d0,
    .param .u32 d1,
    .param .u32 d2,
    .param .u32 dim,
    .param .u32 outn
)
{
    .reg .pred %p<4>;
    .reg .b32 %r<24>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<4>;

    ld.param.u64 %rd1, [p_in];
    ld.param.u64 %rd2, [p_out];
    ld.param.u32 %r1, [d0];
    ld.param.u32 %r2, [d1];
    ld.param.u32 %r3, [d2];
    ld.param.u32 %r4, [dim];
    ld.param.u32 %r5, [outn];

    mov.u32 %r10, %ctaid.x;
    mov.u32 %r11, %ntid.x;
    mov.u32 %r12, %tid.x;
    mad.lo.u32 %r13, %r10, %r11, %r12;

    setp.ge.u32 %p1, %r13, %r5;
    @%p1 bra L_EXIT;

    setp.eq.u32 %p2, %r4, 0;
    @%p2 bra L_DIM0;
    setp.eq.u32 %p3, %r4, 2;
    @%p3 bra L_DIM2;

    div.u32 %r14, %r13, %r3;
    rem.u32 %r15, %r13, %r3;
    mov.u32 %r20, %r2;
    cvt.u64.u32 %rd14, %r14;
    cvt.u64.u32 %rd15, %r2;
    mul.lo.u64 %rd14, %rd14, %rd15;
    cvt.u64.u32 %rd15, %r3;
    mul.lo.u64 %rd14, %rd14, %rd15;
    cvt.u64.u32 %rd15, %r15;
    add.u64 %rd10, %rd14, %rd15;
    cvt.u64.u32 %rd11, %r3;
    bra L_COMMON;

L_DIM0:
    mov.u32 %r20, %r1;
    cvt.u64.u32 %rd10, %r13;
    cvt.u64.u32 %rd14, %r2;
    cvt.u64.u32 %rd15, %r3;
    mul.lo.u64 %rd11, %rd14, %rd15;
    bra L_COMMON;

L_DIM2:
    mov.u32 %r20, %r3;
    cvt.u64.u32 %rd14, %r13;
    cvt.u64.u32 %rd15, %r3;
    mul.lo.u64 %rd10, %rd14, %rd15;
    mov.u64 %rd11, 1;

L_COMMON:
    shl.b64 %rd10, %rd10, 2;
    shl.b64 %rd11, %rd11, 2;
    add.u64 %rd12, %rd1, %rd10;
    cvt.u64.u32 %rd14, %r13;
    shl.b64 %rd14, %rd14, 2;
    add.u64 %rd13, %rd2, %rd14;

    mov.b32 %f0, 0f7F800000;
    mov.u32 %r21, 0;

L_LOOP:
    setp.ge.u32 %p1, %r21, %r20;
    @%p1 bra L_STORE;
    ld.global.f32 %f1, [%rd12];
    min.f32 %f0, %f0, %f1;
    add.u64 %rd12, %rd12, %rd11;
    add.u32 %r21, %r21, 1;
    bra L_LOOP;

L_STORE:
    st.global.f32 [%rd13], %f0;

L_EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("min_reduce_dim_kernel")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dim() != 3 or x.dtype != torch.float32:
            raise RuntimeError("unsupported input")

        dim = self.dim
        if dim < 0:
            dim += x.dim()
        if dim < 0 or dim >= 3:
            raise RuntimeError("unsupported dim")

        d0 = int(x.size(0))
        d1 = int(x.size(1))
        d2 = int(x.size(2))
        out_shape = tuple(x.shape[:dim]) + tuple(x.shape[dim + 1:])
        out = torch.empty(out_shape, device=x.device, dtype=x.dtype)

        out_numel = int(out.numel())
        if out_numel == 0:
            return out

        block_x = 256
        grid_x = (out_numel + block_x - 1) // block_x
        module = _get_ptx_module()
        module.launch(
            "min_reduce_dim_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, u32(d0), u32(d1), u32(d2), u32(dim), u32(out_numel)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

